import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"沁园春·瞬息浮生","description":"","frontmatter":{"title":"沁园春·瞬息浮生","date":"2026-11-11T00:00:00.000Z","seq":97,"categories":["美文","纳兰性德词"],"collection":"《纳兰性德词》","tags":["纳兰性德词","清"],"poem":true,"author":"纳兰性德","source_book":"纳兰性德词"},"headers":[],"relativePath":"blogs/纳兰性德词/沁园春·瞬息浮生.md","filePath":"blogs/纳兰性德词/沁园春·瞬息浮生.md"}'),o={name:"blogs/纳兰性德词/沁园春·瞬息浮生.md"};function c(l,a,n,_,r,m){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="沁园春·瞬息浮生" tabindex="-1">沁园春·瞬息浮生 <a class="header-anchor" href="#沁园春·瞬息浮生" aria-label="Permalink to &quot;沁园春·瞬息浮生&quot;">​</a></h1><p class="poem-meta">清 · 纳兰性德</p><div class="poem"><p class="poem-stanza">丁巳重阳前三日，梦亡妇淡妆素服，执手硬咽</p><p class="poem-stanza">语多不复能</p><p class="poem-stanza">但临别有云：“衔恨愿为天上月，年年犹得向郎圆”</p><p class="poem-stanza">妇素未工诗，不知何以得此也</p><p class="poem-stanza">觉后感赋长调:</p><p class="poem-stanza">瞬息浮生，薄命如斯，低徊怎忘？</p><p class="poem-stanza">记绣榻闲时，并吹红雨，雕阑曲处，同倚斜阳。</p><p class="poem-stanza">梦好难留，诗残莫续，赢得更深哭一场。</p><p class="poem-stanza">遗容在，只灵飙一转，未许端详。</p><p class="poem-stanza">重寻碧落茫茫，料短发，朝来定有霜。</p><p class="poem-stanza">便人间天上，尘缘未断，春花秋叶，触绪还伤。</p><p class="poem-stanza">欲结绸缪，翻惊摇落，减尽荀衣昨日香。</p><p class="poem-stanza">真无奈，倩声声邻笛，谱出回肠。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
